function byP(p){ var q=1-p; return { p:p, q:q, AA:p*p, Aa:2*p*q, aa:q*q }; }
function byQ(q){ var p=1-q; return { p:p, q:q, AA:p*p, Aa:2*p*q, aa:q*q }; }
function alleleFreqs(nAA, nAa, naa){
  var n=2*(nAA+nAa+naa);
  if(n===0) return {p:0, q:0};
  var p=(2*nAA + nAa)/n;
  var q=(2*naa + nAa)/n;
  return { p:p, q:q, AA:p*p, Aa:2*p*q, aa:q*q };
}
var EXPORTS={ byP:byP, byQ:byQ, alleleFreqs:alleleFreqs };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HardyWeinbergForgePure = EXPORTS; }
